    function showAttendanceReport(){const rows=attendance.slice().reverse();openModal('Reportes de Asistencia · demo',`<div class="toolbar"><button class="btn btn-light" id="downloadAttendanceReport" type="button">Descargar Excel/CSV</button><span class="pill">${rows.length} registros</span></div><div class="table-wrap"><table style="min-width:650px"><thead><tr><th>Fecha</th><th>Empleado</th><th>Código</th><th>Hora</th><th>Tipo</th><th>Dispositivo</th></tr></thead><tbody>${rows.length?rows.map(row=>`<tr><td>${escapeHtml(row.date)}</td><td>${escapeHtml(row.employeeName)}</td><td>${escapeHtml(row.employeeCode)}</td><td>${escapeHtml(row.time)}</td><td>${escapeHtml(row.type)}</td><td>${escapeHtml(row.device)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">Todavía no hay asistencias guardadas en esta demo.</td></tr>'}</tbody></table></div><p class="hint">Reporte local basado en las marcas de asistencia de este navegador.</p><div class="dialog-actions"><button class="btn btn-light" id="attendanceReportClose">Cerrar</button></div>`);document.querySelector('#attendanceReportClose').onclick=closeModal;document.querySelector('#downloadAttendanceReport').onclick=()=>{if(!rows.length){showToast('No hay registros para descargar.');return}downloadCsv('LLANQUE_asistencia_demo.csv',['Fecha','Empleado','Código','Hora','Tipo','Dispositivo'],rows.map(row=>[row.date,row.employeeName,row.employeeCode,row.time,row.type,row.device]));showToast('Reporte de asistencia descargado.')}}
