    function showVacationForm(){openModal('Solicitar Vacaciones · demo',`<div class="grid"><div class="field"><label for="vacationStart">Fecha de inicio *</label><input id="vacationStart" type="date" required></div><div class="field"><label for="vacationEnd">Fecha de retorno *</label><input id="vacationEnd" type="date" required></div><div class="field full"><label for="vacationReason">Observación</label><textarea id="vacationReason" placeholder="Motivo opcional"></textarea></div></div><p class="hint">La solicitud queda guardada localmente como pendiente; no se envía al personal ni a Xiren.</p><div class="dialog-actions"><button class="btn btn-light" id="vacationCancel">Cancelar</button><button class="btn btn-green" id="vacationSave">Guardar solicitud demo</button></div>`);document.querySelector('#vacationCancel').onclick=closeModal;document.querySelector('#vacationSave').onclick=()=>{const start=document.querySelector('#vacationStart').value,end=document.querySelector('#vacationEnd').value,reason=document.querySelector('#vacationReason').value.trim();if(!start||!end||end<start){showToast('Selecciona fechas válidas para las vacaciones.');return}const requests=JSON.parse(localStorage.getItem('llanque-demo-vacations')||'[]');requests.push({id:'VAC-'+Date.now().toString().slice(-6),start,end,reason,status:'Pendiente',created:new Date().toLocaleString('es-BO')});localStorage.setItem('llanque-demo-vacations',JSON.stringify(requests));closeModal();showToast('Solicitud de vacaciones guardada en la demo.')}}
