    function createEmployeeCode(){const draw=()=>{openModal('Códigos del personal · demo',`<div class="history-list">${personnel.length?personnel.map((person,index)=>`<div class="history-item"><div><strong>${escapeHtml(person.name)}</strong><br><small>Código: ${escapeHtml(person.code)}</small></div><div><button type="button" class="mini-action" data-edit-employee="${index}">Corregir</button><button type="button" class="mini-action danger-action" data-delete-employee="${index}">Borrar</button></div></div>`).join(''):'<div class="empty">Aún no hay códigos de personal.</div>'}</div><div class="grid" style="margin-top:15px"><div class="field full"><label for="employeeNameNew">Nombre del personal *</label><input id="employeeNameNew" placeholder="Nombre y apellido" required></div><div class="field full"><label for="employeeCodeNew">Código de empleado *</label><input id="employeeCodeNew" placeholder="Ej: E001" required></div></div><p class="hint">Los cambios se guardan únicamente en este navegador. Los registros anteriores de asistencia conservan sus datos originales.</p><div class="dialog-actions"><button class="btn btn-light" id="employeeCodeCancel">Cerrar</button><button class="btn btn-green" id="employeeCodeSave">Crear código demo</button></div>`);const nameInput=document.querySelector('#employeeNameNew'),codeInput=document.querySelector('#employeeCodeNew'),save=document.querySelector('#employeeCodeSave');document.querySelector('#employeeCodeCancel').onclick=closeModal;document.querySelectorAll('[data-edit-employee]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.editEmployee),person=personnel[index];nameInput.value=person.name;codeInput.value=person.code;save.dataset.editIndex=String(index);save.textContent='Guardar corrección';nameInput.focus()});document.querySelectorAll('[data-delete-employee]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.deleteEmployee),person=personnel[index];if(!confirm(`¿Borrar el código ${person.code} de ${person.name}?`))return;const used=document.querySelector('#attendanceEmployeeCode').value.trim().toUpperCase()===person.code.toUpperCase();personnel.splice(index,1);localStorage.setItem('llanque-demo-personnel',JSON.stringify(personnel));if(used)document.querySelector('#attendanceEmployeeCode').value='';renderAttendance();draw();showToast('Código de personal borrado de la demo.')});save.onclick=()=>{const name=nameInput.value.trim(),code=codeInput.value.trim().toUpperCase(),editing=save.dataset.editIndex!==undefined,index=Number(save.dataset.editIndex);if(!name||!code){showToast('Ingresa nombre y código del empleado.');return}if(personnel.some((person,i)=>i!==index&&person.code.toLowerCase()===code.toLowerCase())){showToast('Ese código ya está registrado.');return}if(editing){const oldCode=personnel[index]?.code;personnel[index]={...personnel[index],name,code};if(document.querySelector('#attendanceEmployeeCode').value.trim().toUpperCase()===String(oldCode).toUpperCase())document.querySelector('#attendanceEmployeeCode').value=code;delete save.dataset.editIndex;save.textContent='Crear código demo';showToast('Código de personal corregido.')}else{personnel.push({name,code});document.querySelector('#attendanceEmployeeCode').value=code;showToast(`Código ${code} creado para ${name}.`)}localStorage.setItem('llanque-demo-personnel',JSON.stringify(personnel));renderAttendance();draw()}};draw()}
    function configureDeviceCode(){openModal('Código de dispositivo demo',`<div class="field full"><label for="deviceCodeNew">Código del Dispositivo *</label><input id="deviceCodeNew" value="${escapeHtml(deviceCode)}" placeholder="Ej: DISP-001" required></div><p class="hint">Puedes corregirlo o borrarlo. Se guarda solo en este navegador.</p><div class="dialog-actions"><button class="btn btn-red" id="deviceCodeDelete" ${deviceCode?'':'disabled'}>Borrar código</button><button class="btn btn-light" id="deviceCodeCancel">Cancelar</button><button class="btn btn-green" id="deviceCodeSave">Guardar corrección</button></div>`);document.querySelector('#deviceCodeCancel').onclick=closeModal;document.querySelector('#deviceCodeSave').onclick=()=>{const code=document.querySelector('#deviceCodeNew').value.trim().toUpperCase();if(!code){showToast('Escribe el código o usa Borrar código.');return}deviceCode=code;localStorage.setItem('llanque-demo-device-code',deviceCode);document.querySelector('#attendanceDeviceCode').value=deviceCode;closeModal();showToast('Código de dispositivo corregido.')};document.querySelector('#deviceCodeDelete').onclick=()=>{if(!confirm('¿Borrar el código del dispositivo de esta demo?'))return;deviceCode='';localStorage.removeItem('llanque-demo-device-code');document.querySelector('#attendanceDeviceCode').value='';closeModal();showToast('Código de dispositivo borrado de la demo local.')}}
    function registerAttendance(type){if(!deviceCode){showToast('Primero crea el código del dispositivo.');return}const employeeCode=document.querySelector('#attendanceEmployeeCode').value.trim().toUpperCase();if(!employeeCode){showToast('Ingresa el código del empleado.');document.querySelector('#attendanceEmployeeCode').focus();return}const employee=personnel.find(p=>p.code.toUpperCase()===employeeCode);if(!employee){showToast('Ese código no existe. Usa “Gestionar códigos” para crearlo.');return}const now=new Date(),time=now.toLocaleTimeString('es-BO',{hour12:false}),hour=String(now.getHours()).padStart(2,'0'),minute=String(now.getMinutes()).padStart(2,'0'),onTime=`${hour}:${minute}`<='08:00';attendance.push({employeeCode,employeeName:employee.name,date:localDateValue(),time,type,device:deviceCode});localStorage.setItem('llanque-demo-attendance',JSON.stringify(attendance));document.querySelector('#attendanceEmployeeCode').value='';const feedback=document.querySelector('#attendanceFeedback');feedback.hidden=false;feedback.className=`attendance-feedback ${type==='Entrada'?(onTime?'punctual':'late'):'departure'}`;feedback.textContent=type==='Entrada'?(onTime?`🎉 ¡Llegaste a tiempo, ${employee.name}! Marcaste a las ${time}. Puntualidad nivel leyenda; el reloj te aplaude. 👏`:`☕ ¡Entrada registrada, ${employee.name}, a las ${time}! Hoy el despertador pidió revancha 😄.`):`✅ ¡Salida registrada a las ${time}, ${employee.name}! Jornada guardada. ¡Que descanses! 🌟`;clearTimeout(attendanceFeedbackTimer);attendanceFeedbackTimer=setTimeout(()=>{feedback.hidden=true},10000);showToast(`${type} registrada a las ${time}.`)}
    document.querySelector('#createEmployeeCode').onclick=createEmployeeCode;document.querySelector('#configureDeviceCode').onclick=configureDeviceCode;document.querySelector('#attendanceDeviceCode').addEventListener('change',event=>{deviceCode=event.target.value.trim().toUpperCase();event.target.value=deviceCode;if(deviceCode)localStorage.setItem('llanque-demo-device-code',deviceCode);else localStorage.removeItem('llanque-demo-device-code');showToast('Código del dispositivo actualizado.')});document.querySelector('#registerAttendanceEntry').onclick=()=>registerAttendance('Entrada');document.querySelector('#registerAttendanceExit').onclick=()=>registerAttendance('Salida');
    function toggleCodeVisibility(inputId,buttonId,label){const input=document.querySelector(`#${inputId}`),button=document.querySelector(`#${buttonId}`);button.onclick=()=>{const show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',`${show?'Ocultar':'Mostrar'} ${label}`);button.title=`${show?'Ocultar':'Mostrar'} código`;button.textContent=show?'◉':'◎'}}toggleCodeVisibility('attendanceEmployeeCode','toggleEmployeeCode','código de empleado');toggleCodeVisibility('attendanceDeviceCode','toggleDeviceCode','código del dispositivo');
