    function persistDemo(){localStorage.setItem('llanque-demo-inventory',JSON.stringify(catalog));localStorage.setItem('llanque-demo-movements',JSON.stringify(movements));localStorage.setItem('llanque-demo-history',JSON.stringify(histories))}
    function downloadCsv(filename,headers,rows){const protect=value=>{const text=String(value??''),safe=/^[\s]*[=+@\-]/.test(text)?`'${text}`:text;return `"${safe.replace(/"/g,'""')}"`};const csv='sep=;\r\n'+[headers,...rows].map(row=>row.map(protect).join(';')).join('\r\n');const blob=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
