    function switchView(view){document.body.classList.toggle('attendance-active',view==='attendance');document.querySelector('#homeView').hidden=view!=='home';document.querySelector('#saleView').hidden=view!=='sale';document.querySelectorAll('.module-view').forEach(x=>x.hidden=x.id!==({inventory:'inventoryView',movements:'movementsView',kardex:'kardexView',people:'peopleView',attendance:'attendanceView'}[view]));document.querySelectorAll('.module-nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const labels={home:'Inicio',sale:'Registrar Salida por Venta',inventory:'Inventario de Productos',movements:'Movimientos de Inventario',kardex:'Kardex de Inventario',people:'Personas / Clientes',attendance:'Asistencia del Personal'};document.querySelector('#crumbText').textContent=labels[view];if(view==='inventory')renderInventory();if(view==='movements')renderMovements();if(view==='kardex')renderKardex();if(view==='people')renderPeople();if(view==='attendance')renderAttendance()}
