    function fillProductRow(row,p){row.dataset.code=p[0];row.querySelector('.code').value=p[0];row.querySelector('.name').textContent=p[1];row.querySelector('.unit').innerHTML='<option>Unidad</option><option>Caja</option><option>Paquete</option>';row.querySelector('.unit').disabled=false;row.querySelector('.qty').disabled=false;row.querySelector('.qty').value=1;row.querySelector('.unit-price').disabled=false;row.querySelector('.unit-price').value=p[2].toFixed(2);row.querySelector('.line-discount').disabled=false;row.querySelector('.stock').textContent=p[3];updateBusinessStatus(row,false);calculate()}
