    function calculate(){let sub=0,disc=0;tbody.querySelectorAll('tr').forEach(tr=>{const p=catalog.find(x=>x[0]===tr.dataset.code),price=p?Math.max(0,Number(tr.querySelector('.unit-price').value)||0):0,qty=p?Math.max(0,Number(tr.querySelector('.qty').value)||0):0,d=p?Math.min(price*qty,Math.max(0,Number(tr.querySelector('.line-discount').value)||0)):0,gross=price*qty,amount=Math.max(0,gross-d);tr.querySelector('.line-subtotal').textContent=fmt(gross);tr.querySelector('.line-total').textContent=fmt(amount);tr.querySelector('.stock').textContent=p?p[3]:'-';sub+=gross;disc+=d});const extra=Math.min(Math.max(0,sub-disc),Math.max(0,Number(document.querySelector('#discount').value)||0));document.querySelector('#subtotal').textContent=fmt(sub);document.querySelector('#discounts').textContent=fmt(disc);document.querySelector('#extraDiscount').textContent=fmt(extra);document.querySelector('#total').textContent=fmt(Math.max(0,sub-disc-extra));if(!document.querySelector('#mixedPayment').hidden)checkPayLines()}
